import { readFile, writeFile } from 'node:fs/promises'
const source = JSON.parse(
  await readFile(new URL('../i18n/locales/zh-CN.json', import.meta.url), 'utf8')
)
const entries = Object.entries(source).map(([key, value]) => [value, key])
await writeFile(
  new URL('../shared/message-keys.ts', import.meta.url),
  '// Generated by scripts/sync-message-keys.mjs; source text stays readable at call sites.\nexport const sourceKeys = new Map<string, string>(' +
    JSON.stringify(entries, null, 2) +
    ')\n'
)
